"}]},"parent_tool_use_id":null,"session_id":"74407488-eb72-46a1-b9cc-9b0c4506fd7e","uuid":"6eba6f4c-fab1-4b85-bcb4-64a81b594e41","tool_use_result":{"type":"text","file":{"filePath":"/Users/nasseralbusaidi/Desktop/makingMoney/clients/ROH/dashboard/lib/mock-data.ts","content":"// Mock RFID data layer for ROH Chair Tracking System
// This module simulates data from the RFID gate reader.
// Replace with real API calls when hardware is connected.

export type ChairStatus = "in" | "out";

export interface Chair {
  id: number;
  tagId: string;
  status: ChairStatus;
  lastMovement: Date;
  totalTimeOutsideMs: number;
}

export interface Movement {
  id: string;
  chairId: number;
  tagId: string;
  direction: "in" | "out";
  timestamp: Date;
}

export interface AlertConfig {
  bulkDepartureThreshold: number;
  bulkDepartureWindowMinutes: number;
  missingChairHours: number;
  notificationEmail: string;
}

const TOTAL_CHAIRS = 100;

function generateTagId(n: number): string {
  return `ROH-${String(n).padStart(3, "0")}`;
}

function seededRandom(seed: number): number {
  const x = Math.sin(seed + 1) * 10000;
  return x - Math.floor(x);
}

function seededDate(seed: number, start: number, end: number): Date {
  return new Date(start + seededRandom(seed) * (end - start));
}

export function msToReadable(ms: number): string {
  const hours = Math.floor(ms / 3600000);
  const minutes = Math.floor((ms % 3600000) / 60000);
  if (hours > 0) return `${hours}h ${minutes}m`;
  return `${minutes}m`;
}

const nowMs = Date.now();
const oneWeekAgoMs = nowMs - 7 * 24 * 3600000;

// Pick 22 chairs to be "outside" using a fixed list (no loop risk)
const OUT_CHAIR_IDS = new Set([3, 7, 12, 15, 19, 24, 28, 33, 37, 41, 46, 50, 55, 60, 64, 68, 73, 77, 82, 86, 91, 95]);

export const chairs: Chair[] = Array.from({ length: TOTAL_CHAIRS }, (_, i) => {
  const id = i + 1;
  const isOut = OUT_CHAIR_IDS.has(id);
  const lastMoved = seededDate(id * 17, oneWeekAgoMs, nowMs);
  const timeOutMs = isOut
    ? seededRandom(id) * 12 * 3600000
    : seededRandom(id + 100) * 2 * 3600000;
  return {
    id,
    tagId: generateTagId(id),
    status: isOut ? "out" : "in",
    lastMovement: lastMoved,
    totalTimeOutsideMs: timeOutMs,
  };
});

function generateMovements(): Movement[] {
  const list: Movement[] = [];

  for (let i = 0; i < 200; i++) {
    const chairId = Math.floor(seededRandom(i * 7 + 1) * TOTAL_CHAIRS) + 1;
    const direction: "in" | "out" = seededRandom(i * 7 + 2) > 0.5 ? "out" : "in";
    const timestamp = seededDate(i * 7 + 3, oneWeekAgoMs, nowMs);
    list.push({
      id: `mov-${i}`,
      chairId,
      tagId: generateTagId(chairId),
      direction,
      timestamp,
    });
  }

  for (let i = 0; i < 10; i++) {
    const minsAgo = (i + 1) * 3 + Math.floor(seededRandom(i + 500) * 5);
    const chairId = Math.floor(seededRandom(i * 13 + 999) * TOTAL_CHAIRS) + 1;
    const direction: "in" | "out" = i % 3 === 0 ? "in" : "out";
    list.push({
      id: `mov-recent-${i}`,
      chairId,
      tagId: generateTagId(chairId),
      direction,
      timestamp: new Date(nowMs - minsAgo * 60000),
    });
  }

  return list.sort((a, b) => b.timestamp.getTime() - a.timestamp.getTime());
}

export const movements: Movement[] = generateMovements();

export const stats = {
  total: TOTAL_CHAIRS,
  inStorage: chairs.filter((c) => c.status === "in").length,
  outsideStorage: chairs.filter((c) => c.status === "out").length,
};

export function getStatusLevel(inStorage: number, total: number): "green" | "amber" | "red" {
  const pct = inStorage / total;
  if (pct >= 0.9) return "green";
  if (pct >= 0.7) return "amber";
  return "red";
}

export const recentMovements = movements.slice(0, 10);

export const defaultAlertConfig: AlertConfig = {
  bulkDepartureThreshold: 10,
  bulkDepartureWindowMinutes: 30,
  missingChairHours: 24,
  notificationEmail: "admin@roh.om",
};
