import { useState } from "react";
import { chairs, msToReadable } from "@/lib/mock-data";

export default function ChairDirectory() {
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState<"all" | "in" | "out">("all");

  const filtered = chairs.filter((c) => {
    const matchesSearch =
      search === "" ||
      c.tagId.toLowerCase().includes(search.toLowerCase()) ||
      String(c.id).includes(search);
    const matchesStatus = statusFilter === "all" || c.status === statusFilter;
    return matchesSearch && matchesStatus;
  });

  return (
    <div className="space-y-8">
      <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-4">
        <div>
          <h1
            className="text-3xl font-bold tracking-tight"
            style={{ fontFamily: "var(--font-display)" }}
          >
            Chair Directory
          </h1>
          <p className="mt-1 text-sm" style={{ color: "var(--text-muted)" }}>
            {filtered.length} of {chairs.length} chairs
          </p>
        </div>
      </div>

      {/* Filters */}
      <div className="flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <span
            className="absolute left-4 top-1/2 -translate-y-1/2 text-sm"
            style={{ color: "var(--text-muted)" }}
          >
            ⌕
          </span>
          <input
            type="text"
            placeholder="Search by chair # or tag ID..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full rounded-xl pl-10 pr-4 py-3 text-sm focus:outline-none transition-all"
            style={{
              background: "var(--bg-card)",
              border: "1px solid var(--border)",
              color: "var(--text-primary)",
            }}
          />
        </div>
        <div
          className="flex rounded-xl overflow-hidden"
          style={{ border: "1px solid var(--border)" }}
        >
          {(["all", "in", "out"] as const).map((s) => (
            <button
              key={s}
              onClick={() => setStatusFilter(s)}
              className="px-5 py-3 text-sm font-medium transition-all"
              style={{
                background:
                  statusFilter === s ? "var(--gold-glow)" : "var(--bg-card)",
                color:
                  statusFilter === s ? "var(--gold)" : "var(--text-secondary)",
                borderRight: s !== "out" ? "1px solid var(--border)" : "none",
              }}
            >
              {s === "all" ? "All" : s === "in" ? "In Storage" : "Outside"}
            </button>
          ))}
        </div>
      </div>

      {/* Table */}
      <div
        className="rounded-xl overflow-hidden"
        style={{
          background: "var(--bg-card)",
          border: "1px solid var(--border)",
        }}
      >
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr style={{ borderBottom: "1px solid var(--border)" }}>
                {["Chair", "Tag ID", "Status", "Last Movement", "Time Outside"].map(
                  (h) => (
                    <th
                      key={h}
                      className="text-left px-6 py-4 text-[11px] font-semibold uppercase tracking-[0.15em]"
                      style={{ color: "var(--text-muted)" }}
                    >
                      {h}
                    </th>
                  )
                )}
              </tr>
            </thead>
            <tbody>
              {filtered.map((chair, i) => (
                <tr
                  key={chair.id}
                  className="transition-colors"
                  style={{
                    borderBottom:
                      i < filtered.length - 1
                        ? "1px solid var(--border-subtle)"
                        : "none",
                  }}
                >
                  <td className="px-6 py-4">
                    <span
                      className="font-semibold"
                      style={{ color: "var(--text-primary)" }}
                    >
                      #{chair.id}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                    <span
                      className="font-mono text-xs"
                      style={{ color: "var(--text-secondary)" }}
                    >
                      {chair.tagId}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                    <span
                      className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-semibold"
                      style={{
                        background:
                          chair.status === "in"
                            ? "var(--emerald-dim)"
                            : "var(--amber-dim)",
                        color:
                          chair.status === "in"
                            ? "var(--emerald)"
                            : "var(--amber)",
                      }}
                    >
                      <span
                        className="w-1.5 h-1.5 rounded-full"
                        style={{
                          background:
                            chair.status === "in"
                              ? "var(--emerald)"
                              : "var(--amber)",
                        }}
                      />
                      {chair.status === "in" ? "In Storage" : "Outside"}
                    </span>
                  </td>
                  <td
                    className="px-6 py-4 text-xs tabular-nums"
                    style={{ color: "var(--text-secondary)" }}
                  >
                    {chair.lastMovement.toLocaleString("en-GB", {
                      day: "2-digit",
                      month: "short",
                      hour: "2-digit",
                      minute: "2-digit",
                    })}
                  </td>
                  <td
                    className="px-6 py-4 text-xs font-mono"
                    style={{ color: "var(--text-secondary)" }}
                  >
                    {msToReadable(chair.totalTimeOutsideMs)}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          {filtered.length === 0 && (
            <div
              className="text-center py-16 text-sm"
              style={{ color: "var(--text-muted)" }}
            >
              No chairs match your search.
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
