import { useState, useMemo } from "react";
import { movements } from "@/lib/mock-data";

type DirectionFilter = "all" | "in" | "out";

function formatDateTime(date: Date): string {
  return date.toLocaleString("en-GB", {
    day: "2-digit",
    month: "short",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  });
}

function exportCSV(data: typeof movements) {
  const header = "Movement ID,Chair #,Tag ID,Direction,Timestamp";
  const rows = data.map(
    (m) => `${m.id},${m.chairId},${m.tagId},${m.direction},${m.timestamp.toISOString()}`
  );
  const csv = [header, ...rows].join("\n");
  const blob = new Blob([csv], { type: "text/csv" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `roh-movements-${new Date().toISOString().split("T")[0]}.csv`;
  a.click();
  URL.revokeObjectURL(url);
}

export default function MovementHistory() {
  const [chairSearch, setChairSearch] = useState("");
  const [direction, setDirection] = useState<DirectionFilter>("all");
  const [dateFrom, setDateFrom] = useState("");
  const [dateTo, setDateTo] = useState("");
  const [page, setPage] = useState(1);
  const PAGE_SIZE = 20;

  const filtered = useMemo(() => {
    return movements.filter((m) => {
      if (chairSearch) {
        const q = chairSearch.toLowerCase();
        if (!m.tagId.toLowerCase().includes(q) && !String(m.chairId).includes(q)) return false;
      }
      if (direction !== "all" && m.direction !== direction) return false;
      if (dateFrom && m.timestamp < new Date(dateFrom)) return false;
      if (dateTo) {
        const end = new Date(dateTo);
        end.setDate(end.getDate() + 1);
        if (m.timestamp >= end) return false;
      }
      return true;
    });
  }, [chairSearch, direction, dateFrom, dateTo]);

  const paginated = filtered.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);
  const totalPages = Math.ceil(filtered.length / PAGE_SIZE);
  const resetPage = () => setPage(1);

  const inputStyle = {
    background: "var(--bg-secondary)",
    border: "1px solid var(--border)",
    color: "var(--text-primary)",
  };

  return (
    <div className="space-y-8">
      <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-4">
        <div>
          <h1
            className="text-3xl font-bold tracking-tight"
            style={{ fontFamily: "var(--font-display)" }}
          >
            Movement History
          </h1>
          <p className="mt-1 text-sm" style={{ color: "var(--text-muted)" }}>
            {filtered.length} movements recorded
          </p>
        </div>
        <button
          onClick={() => exportCSV(filtered)}
          className="inline-flex items-center gap-2 px-5 py-2.5 rounded-xl text-sm font-semibold transition-all"
          style={{
            background: "var(--gold-glow)",
            color: "var(--gold)",
            border: "1px solid rgba(201, 169, 110, 0.2)",
          }}
        >
          ↓ Export CSV
        </button>
      </div>

      {/* Filters */}
      <div
        className="rounded-xl p-5 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4"
        style={{
          background: "var(--bg-card)",
          border: "1px solid var(--border)",
        }}
      >
        <div>
          <label
            className="block text-[11px] font-semibold uppercase tracking-[0.15em] mb-2"
            style={{ color: "var(--text-muted)" }}
          >
            Chair / Tag
          </label>
          <input
            type="text"
            placeholder="Search..."
            value={chairSearch}
            onChange={(e) => { setChairSearch(e.target.value); resetPage(); }}
            className="w-full rounded-lg px-3 py-2.5 text-sm focus:outline-none"
            style={inputStyle}
          />
        </div>
        <div>
          <label
            className="block text-[11px] font-semibold uppercase tracking-[0.15em] mb-2"
            style={{ color: "var(--text-muted)" }}
          >
            Direction
          </label>
          <select
            value={direction}
            onChange={(e) => { setDirection(e.target.value as DirectionFilter); resetPage(); }}
            className="w-full rounded-lg px-3 py-2.5 text-sm focus:outline-none"
            style={inputStyle}
          >
            <option value="all">All directions</option>
            <option value="out">Out only</option>
            <option value="in">In only</option>
          </select>
        </div>
        <div>
          <label
            className="block text-[11px] font-semibold uppercase tracking-[0.15em] mb-2"
            style={{ color: "var(--text-muted)" }}
          >
            From
          </label>
          <input
            type="date"
            value={dateFrom}
            onChange={(e) => { setDateFrom(e.target.value); resetPage(); }}
            className="w-full rounded-lg px-3 py-2.5 text-sm focus:outline-none"
            style={inputStyle}
          />
        </div>
        <div>
          <label
            className="block text-[11px] font-semibold uppercase tracking-[0.15em] mb-2"
            style={{ color: "var(--text-muted)" }}
          >
            To
          </label>
          <input
            type="date"
            value={dateTo}
            onChange={(e) => { setDateTo(e.target.value); resetPage(); }}
            className="w-full rounded-lg px-3 py-2.5 text-sm focus:outline-none"
            style={inputStyle}
          />
        </div>
      </div>

      {/* Table */}
      <div
        className="rounded-xl overflow-hidden"
        style={{
          background: "var(--bg-card)",
          border: "1px solid var(--border)",
        }}
      >
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr style={{ borderBottom: "1px solid var(--border)" }}>
                {["Timestamp", "Chair", "Tag ID", "Direction"].map((h) => (
                  <th
                    key={h}
                    className="text-left px-6 py-4 text-[11px] font-semibold uppercase tracking-[0.15em]"
                    style={{ color: "var(--text-muted)" }}
                  >
                    {h}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {paginated.map((m, i) => (
                <tr
                  key={m.id}
                  className="transition-colors"
                  style={{
                    borderBottom:
                      i < paginated.length - 1
                        ? "1px solid var(--border-subtle)"
                        : "none",
                  }}
                >
                  <td
                    className="px-6 py-4 text-xs tabular-nums whitespace-nowrap"
                    style={{ color: "var(--text-secondary)" }}
                  >
                    {formatDateTime(m.timestamp)}
                  </td>
                  <td className="px-6 py-4">
                    <span className="font-semibold" style={{ color: "var(--text-primary)" }}>
                      #{m.chairId}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                    <span
                      className="font-mono text-xs"
                      style={{ color: "var(--text-secondary)" }}
                    >
                      {m.tagId}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                    <span
                      className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-semibold uppercase tracking-wider"
                      style={{
                        background:
                          m.direction === "out" ? "var(--amber-dim)" : "var(--blue-dim)",
                        color:
                          m.direction === "out" ? "var(--amber)" : "var(--blue)",
                      }}
                    >
                      {m.direction}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          {paginated.length === 0 && (
            <div
              className="text-center py-16 text-sm"
              style={{ color: "var(--text-muted)" }}
            >
              No movements match your filters.
            </div>
          )}
        </div>
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex items-center justify-between">
          <p className="text-xs" style={{ color: "var(--text-muted)" }}>
            Page {page} of {totalPages}
          </p>
          <div className="flex gap-2">
            {[
              { label: "← Previous", onClick: () => setPage((p) => Math.max(1, p - 1)), disabled: page === 1 },
              { label: "Next →", onClick: () => setPage((p) => Math.min(totalPages, p + 1)), disabled: page === totalPages },
            ].map((btn) => (
              <button
                key={btn.label}
                onClick={btn.onClick}
                disabled={btn.disabled}
                className="px-4 py-2 text-xs rounded-lg font-medium transition-all disabled:opacity-30"
                style={{
                  background: "var(--bg-card)",
                  color: "var(--text-secondary)",
                  border: "1px solid var(--border)",
                }}
              >
                {btn.label}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}
