// Connects to FastAPI backend at /api/* (proxied via next.config.ts)

export type ChairStatus = "in" | "out";

export interface Chair {
  id: number;
  tagId: string;
  status: ChairStatus;
  lastMovement: string; // ISO 8601
  totalTimeOutsideMs: number;
}

export interface Movement {
  id: string;
  chairId: number;
  tagId: string;
  direction: "in" | "out";
  timestamp: string; // ISO 8601
}

export interface Stats {
  total: number;
  inStorage: number;
  outsideStorage: number;
}

export interface AlertConfig {
  bulkDepartureThreshold: number;
  bulkDepartureWindowMinutes: number;
  missingChairHours: number;
  notificationEmail: string;
}

export interface MovementsResponse {
  movements: Movement[];
  total: number;
  page: number;
  pageSize: number;
}

export interface MovementsParams {
  page?: number;
  pageSize?: number;
  direction?: "in" | "out" | "all";
  chairSearch?: string;
  dateFrom?: string;
  dateTo?: string;
}

// WebSocket event sent by /ws/live
export interface LiveEvent {
  type: "stats_update" | "movement";
  stats?: Stats;
  movement?: Movement;
}

const BASE = "/api";

async function apiFetch<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(`${BASE}${path}`, {
    ...init,
    headers: {
      "Content-Type": "application/json",
      ...(init?.headers ?? {}),
    },
  });
  if (!res.ok) {
    const text = await res.text().catch(() => res.statusText);
    throw new Error(`API ${res.status}: ${text}`);
  }
  return res.json() as Promise<T>;
}

export async function fetchStats(): Promise<Stats> {
  return apiFetch<Stats>("/stats");
}

export async function fetchChairs(): Promise<Chair[]> {
  return apiFetch<Chair[]>("/chairs");
}

export async function fetchMovements(params: MovementsParams = {}): Promise<MovementsResponse> {
  const q = new URLSearchParams();
  if (params.page) q.set("page", String(params.page));
  if (params.pageSize) q.set("page_size", String(params.pageSize));
  if (params.direction && params.direction !== "all") q.set("direction", params.direction);
  if (params.chairSearch) q.set("q", params.chairSearch);
  if (params.dateFrom) q.set("date_from", params.dateFrom);
  if (params.dateTo) q.set("date_to", params.dateTo);
  const qs = q.toString();
  return apiFetch<MovementsResponse>(`/movements${qs ? `?${qs}` : ""}`);
}

export function getMovementsExportUrl(params: MovementsParams = {}): string {
  const q = new URLSearchParams();
  if (params.direction && params.direction !== "all") q.set("direction", params.direction);
  if (params.chairSearch) q.set("q", params.chairSearch);
  if (params.dateFrom) q.set("date_from", params.dateFrom);
  if (params.dateTo) q.set("date_to", params.dateTo);
  const qs = q.toString();
  return `${BASE}/movements/export${qs ? `?${qs}` : ""}`;
}

export async function fetchAlertConfig(): Promise<AlertConfig> {
  return apiFetch<AlertConfig>("/alerts/config");
}

export async function saveAlertConfig(config: AlertConfig): Promise<AlertConfig> {
  return apiFetch<AlertConfig>("/alerts/config", {
    method: "PUT",
    body: JSON.stringify(config),
  });
}

export function msToReadable(ms: number): string {
  const hours = Math.floor(ms / 3600000);
  const minutes = Math.floor((ms % 3600000) / 60000);
  if (hours > 0) return `${hours}h ${minutes}m`;
  return `${minutes}m`;
}

export function getStatusLevel(inStorage: number, total: number): "green" | "amber" | "red" {
  const pct = inStorage / total;
  if (pct >= 0.9) return "green";
  if (pct >= 0.7) return "amber";
  return "red";
}
