import { useState } from "react";
import { defaultAlertConfig } from "@/lib/mock-data";

export default function AlertsConfig() {
  const [config, setConfig] = useState(defaultAlertConfig);
  const [saved, setSaved] = useState(false);

  function handleSave() {
    console.log("Saving alert config:", config);
    setSaved(true);
    setTimeout(() => setSaved(false), 3000);
  }

  function update<K extends keyof typeof config>(key: K, value: (typeof config)[K]) {
    setConfig((prev) => ({ ...prev, [key]: value }));
    setSaved(false);
  }

  const inputStyle = {
    background: "var(--bg-secondary)",
    border: "1px solid var(--border)",
    color: "var(--text-primary)",
  };

  return (
    <div className="space-y-8 max-w-2xl">
      <div>
        <h1
          className="text-3xl font-bold tracking-tight"
          style={{ fontFamily: "var(--font-display)" }}
        >
          Alerts Configuration
        </h1>
        <p className="mt-1 text-sm" style={{ color: "var(--text-muted)" }}>
          Set thresholds for automated monitoring
        </p>
      </div>

      <div
        className="rounded-xl p-8 space-y-8"
        style={{
          background: "var(--bg-card)",
          border: "1px solid var(--border)",
        }}
      >
        {/* Bulk departure */}
        <section className="space-y-5">
          <div>
            <h2
              className="text-base font-semibold"
              style={{ color: "var(--text-primary)" }}
            >
              Bulk Departure Alert
            </h2>
            <p className="text-sm mt-1" style={{ color: "var(--text-muted)" }}>
              Trigger when many chairs leave storage in a short window.
            </p>
          </div>
          <div className="grid grid-cols-2 gap-5">
            <div>
              <label
                className="block text-[11px] font-semibold uppercase tracking-[0.15em] mb-2"
                style={{ color: "var(--text-muted)" }}
              >
                Threshold
              </label>
              <div className="flex items-center gap-3">
                <input
                  type="number"
                  min={1}
                  max={100}
                  value={config.bulkDepartureThreshold}
                  onChange={(e) => update("bulkDepartureThreshold", Number(e.target.value))}
                  className="w-24 rounded-lg px-3 py-2.5 text-sm focus:outline-none"
                  style={inputStyle}
                />
                <span className="text-xs" style={{ color: "var(--text-muted)" }}>
                  chairs
                </span>
              </div>
            </div>
            <div>
              <label
                className="block text-[11px] font-semibold uppercase tracking-[0.15em] mb-2"
                style={{ color: "var(--text-muted)" }}
              >
                Time Window
              </label>
              <div className="flex items-center gap-3">
                <input
                  type="number"
                  min={1}
                  max={1440}
                  value={config.bulkDepartureWindowMinutes}
                  onChange={(e) => update("bulkDepartureWindowMinutes", Number(e.target.value))}
                  className="w-24 rounded-lg px-3 py-2.5 text-sm focus:outline-none"
                  style={inputStyle}
                />
                <span className="text-xs" style={{ color: "var(--text-muted)" }}>
                  minutes
                </span>
              </div>
            </div>
          </div>
          <div
            className="rounded-lg px-4 py-3 text-sm"
            style={{
              background: "var(--amber-dim)",
              color: "var(--amber)",
              border: "1px solid rgba(229, 165, 55, 0.15)",
            }}
          >
            Fires when <strong>{config.bulkDepartureThreshold}+</strong> chairs leave
            within <strong>{config.bulkDepartureWindowMinutes} min</strong>.
          </div>
        </section>

        <div style={{ borderTop: "1px solid var(--border)" }} />

        {/* Missing chair */}
        <section className="space-y-5">
          <div>
            <h2
              className="text-base font-semibold"
              style={{ color: "var(--text-primary)" }}
            >
              Missing Chair Alert
            </h2>
            <p className="text-sm mt-1" style={{ color: "var(--text-muted)" }}>
              Alert when a chair has been outside longer than expected.
            </p>
          </div>
          <div>
            <label
              className="block text-[11px] font-semibold uppercase tracking-[0.15em] mb-2"
              style={{ color: "var(--text-muted)" }}
            >
              Hours Threshold
            </label>
            <div className="flex items-center gap-3">
              <input
                type="number"
                min={1}
                max={168}
                value={config.missingChairHours}
                onChange={(e) => update("missingChairHours", Number(e.target.value))}
                className="w-24 rounded-lg px-3 py-2.5 text-sm focus:outline-none"
                style={inputStyle}
              />
              <span className="text-xs" style={{ color: "var(--text-muted)" }}>
                hours
              </span>
            </div>
          </div>
          <div
            className="rounded-lg px-4 py-3 text-sm"
            style={{
              background: "var(--rose-dim)",
              color: "var(--rose)",
              border: "1px solid rgba(229, 93, 93, 0.15)",
            }}
          >
            Fires if a chair is outside for more than{" "}
            <strong>{config.missingChairHours}h</strong>.
          </div>
        </section>

        <div style={{ borderTop: "1px solid var(--border)" }} />

        {/* Email */}
        <section className="space-y-4">
          <div>
            <h2
              className="text-base font-semibold"
              style={{ color: "var(--text-primary)" }}
            >
              Notification Email
            </h2>
            <p className="text-sm mt-1" style={{ color: "var(--text-muted)" }}>
              Alert destination when thresholds are breached.
            </p>
          </div>
          <input
            type="email"
            value={config.notificationEmail}
            onChange={(e) => update("notificationEmail", e.target.value)}
            placeholder="admin@example.com"
            className="w-full rounded-lg px-4 py-3 text-sm focus:outline-none"
            style={inputStyle}
          />
        </section>

        <div className="flex items-center gap-4 pt-2">
          <button
            onClick={handleSave}
            className="px-7 py-3 rounded-xl text-sm font-bold tracking-wide transition-all"
            style={{
              background: "linear-gradient(135deg, var(--gold), var(--gold-dim))",
              color: "var(--bg-primary)",
            }}
          >
            Save Configuration
          </button>
          {saved && (
            <span
              className="text-sm font-medium"
              style={{ color: "var(--emerald)" }}
            >
              ✓ Saved
            </span>
          )}
        </div>
      </div>

      <div
        className="rounded-xl p-4"
        style={{
          background: "var(--bg-secondary)",
          border: "1px solid var(--border-subtle)",
        }}
      >
        <p className="text-xs" style={{ color: "var(--text-muted)" }}>
          WhatsApp and Telegram notification support planned for a future release.
          Email alerts activate once the backend service is connected.
        </p>
      </div>
    </div>
  );
}
"}}

